func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	var l int64
	fmt.Fscan(in, &n, &k, &l)

	// Precompute factorials and inverse factorials
	fact := make([]int64, n+1)
	ifact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = modMul(fact[i-1], int64(i))
	}
	ifact[n] = modPow(fact[n], MOD-2)
	for i := n; i > 0; i-- {
		ifact[i-1] = modMul(ifact[i], int64(i))
	}

	// Precompute powers of 2 and their inverses
	pow2 := make([]int64, n+1)
	ipow2 := make([]int64, n+1)
	pow2[0] = 1
	for i := 1; i <= n; i++ {
		pow2[i] = modMul(pow2[i-1], 2)
	}
	ipow2[n] = modPow(pow2[n], MOD-2)
	for i := n; i > 0; i-- {
		ipow2[i-1] = modMul(ipow2[i], 2)
	}

	// Precompute binomial coefficients C(n, i)
	C := make([]int64, n+1)
	for i := 0; i <= n; i++ {
		C[i] = modMul(fact[n], modMul(ifact[i], ifact[n-i]))
	}

	// Precompute P(i) = (1 - 2^{-(n-i)})^n
	P := make([]int64, n+1)
	for i := 0; i <= n; i++ {
		exp := n - i
		if exp == 0 {
			P[i] = 0
		} else {
			tmp := modSub(1, ipow2[exp])
			P[i] = modPow(tmp, int64(n))
		}
	}

	// Precompute S(i) = sum_{j=0..i} C(n,j) * P(j)
	S := make([]int64, n+1)
	var cur int64 = 0
	for i := 0; i <= n; i++ {
		cur = modAdd(cur, modMul(C[i], P[i]))
		S[i] = cur
	}

	// Compute sum_{t=k..n} C(n,t) * P(t)
	var sum int64 = 0
	if k <= n {
		sum = modSub(S[n], S[k-1])
	}

	// Multiply by l and by inverse of 2^n
