package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

func modAdd(a, b int64) int64 {
	a += b
	if a >= MOD {
		a -= MOD
	}
	return a
}

func modSub(a, b int64) int64 {
	a -= b
	if a < 0 {
		a += MOD
	}
	return a
}

func modMul(a, b int64) int64 {
	return (a * b) % MOD
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = modMul(res, a)
		}
		a = modMul(a, a)
		e >>= 1
	}
	return res
}

func modInv(a int64) int64 {
	return modPow(a, MOD-2)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	var L int64
	fmt.Fscan(in, &n, &k, &L)

	// Precompute factorials and inverse factorials up to 2n
	maxN := 2 * n
	fact := make([]int64, maxN+1)
	ifact := make([]int64, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = modMul(fact[i-1], int64(i))
	}
	ifact[maxN] = modInv(fact[maxN])
	for i := maxN; i > 0; i-- {
		ifact[i-1] = modMul(ifact[i], int64(i))
	}

	// Precompute inv[i] = modular inverse of i
	inv := make([]int64, maxN+2)
	for i := 1; i <= maxN+1; i++ {
		inv[i] = modInv(int64(i))
	}

	// Precompute p[i] = (1/2)^i
	p := make([]int64, maxN+1)
	p[0] = 1
	inv2 := inv[2]
	for i := 1; i <= maxN; i++ {
		p[i] = modMul(p[i-1], inv2)
	}

	// Precompute binomial coefficients C(n, i)
	C := make([]int64, n+1)
	for i := 0; i <= n; i++ {
		C[i] = modMul(fact[n], modMul(ifact[i], ifact[n-i]))
	}

	// Precompute prefix sums of C(n, i)
	prefC := make([]int64, n+1)
	var s int64 = 0
	for i := 0; i <= n; i++ {
		s = modAdd(s, C[i])
		prefC[i] = s
	}

